kernel_type:
∀ {n : Nat} {s : GoLean.GoCore.ExecState} {c : GoLean.GoCore.Machine.Config} {ch : GoLean.GoCore.Choices}
  {sf : GoLean.GoCore.ExecState} {cf : GoLean.GoCore.Machine.Config} {chf : GoLean.GoCore.Choices},
  GoLean.GoCore.Machine.stepFnIter n s c ch = Except.ok (cf, sf, chf) ↔ GoLean.Semantics.Trace n s c ch sf cf chf

∀ {n : Nat} {s : GoLean.GoCore.ExecState} {c : GoLean.GoCore.Machine.Config} {ch : GoLean.GoCore.Choices}
  {sf : GoLean.GoCore.ExecState} {cf : GoLean.GoCore.Machine.Config} {chf : GoLean.GoCore.Choices},
  GoLean.Semantics.Trace n s c ch sf cf chf → GoLean.GoCore.Machine.Steps c s cf sf

∀ {fuel : Nat} {m : GoLean.GoCore.Machine.MultiConfig} {r : GoLean.GoCore.Machine.RaceState}
  {ch : GoLean.GoCore.Choices} {acc : GoLean.GoString}
  {result : GoLean.GoString × Except GoLean.Stop (GoLean.GoCore.ExecState × GoLean.GoCore.Choices)},
  GoLean.GoCore.Machine.execProgLoopOut fuel m r ch acc = result ↔ GoLean.Semantics.Pool.Run fuel m r ch acc result

∀ {p : GoLean.GoCore.Program} {ps : List GoLean.GoCore.Param} {results : List GoLean.Loc} {s : GoLean.GoCore.ExecState}
  {c : GoLean.GoCore.Machine.Config} {t : GoLean.GoCore.ExecState} {c' : GoLean.GoCore.Machine.Config} {n : Nat}
  {ch ch' : GoLean.GoCore.Choices},
  GoLean.GoCore.RecoveryRuntime.Inv p ps results s c →
    GoLean.GoCore.Machine.stepFnIter n s c ch = Except.ok (c', t, ch') →
      GoLean.GoCore.RecoveryRuntime.Inv p ps results t c'

∀ {p : GoLean.GoCore.Program} {ps : List GoLean.GoCore.Param} {results : List GoLean.Loc} {s : GoLean.GoCore.ExecState}
  {c : GoLean.GoCore.Machine.Config} {fuel : Nat} {ch : GoLean.GoCore.Choices} {t : GoLean.GoCore.ExecState}
  {ch' : GoLean.GoCore.Choices},
  GoLean.GoCore.RecoveryRuntime.Inv p ps results s c →
    GoLean.GoCore.Machine.runConfig fuel s c ch = Except.ok (t, ch') → ch' = ch

∀ {context : GoLean.GoCore.ExecState} {results : List GoLean.Loc} {s : GoLean.GoCore.ExecState}
  {c : GoLean.GoCore.Machine.Config} {fuel : Nat} {ch : GoLean.GoCore.Choices} {t : GoLean.GoCore.ExecState}
  {ch' : GoLean.GoCore.Choices},
  GoLean.GoCore.BooleanRuntime.Inv context results s c →
    GoLean.GoCore.Machine.runConfig fuel s c ch = Except.ok (t, ch') → ch' = ch

∀ {p : GoLean.GoCore.Program} {ps : List GoLean.GoCore.Param} {roots : List GoLean.Loc} {fuel : Nat}
  {s : GoLean.GoCore.ExecState} {c : GoLean.GoCore.Machine.Config} {ch : GoLean.GoCore.Choices}
  {result : Except GoLean.Stop (GoLean.GoCore.ExecState × GoLean.GoCore.Choices)}
  {record : GoLean.GoCore.RecoveryRuntime.AbortRecord},
  GoLean.GoCore.RecoveryRuntime.Inv p ps roots s c →
    GoLean.GoCore.RecoveryRuntime.runConfigWithAbort fuel s c ch = (result, some record) →
      result = Except.error (GoLean.Stop.panic (GoLean.GoCore.Machine.stringPanicHead record.bytes record.recovered))
